#!/bin/bash
#
# Generates a folder of dummy versioned content for testing
# qlab-content-versioning, so you can try the script without
# needing any real media.
#
#   ./make-demo-content.sh [target folder]
#
# Default target is ~/Movies/qlab-versioning-demo
#
# Produces:
#   fileofvideo_v2608182200.png        rust   - point cue 1 here
#   fileofvideo_v2608182205.png        teal   - script should find this
#   otherfileofvideo_v2608182201.png   rust   - point cue 2 here
#   otherfileofvideo_v2608182206.png   teal   - script should find this
#   fileofvideo_vFINAL.png             rust   - deliberately malformed tag,
#                                              should appear under WARNINGS
#
# The rust/teal colour difference means you can see the retarget
# happen on the output stage, not just in the log.

set -e

DEST="${1:-$HOME/Movies/qlab-versioning-demo}"
mkdir -p "$DEST"

OLD_PNG=""
NEW_PNG=""

write_png() {
  printf '%s' "$2" | base64 --decode > "$DEST/$1"
  echo "  $1"
}

echo "Writing demo content to $DEST"
write_png "fileofvideo_v2608182200.png"      "$OLD_PNG"
write_png "fileofvideo_v2608182205.png"      "$NEW_PNG"
write_png "otherfileofvideo_v2608182201.png" "$OLD_PNG"
write_png "otherfileofvideo_v2608182206.png" "$NEW_PNG"
write_png "fileofvideo_vFINAL.png"           "$OLD_PNG"

cat <<EOF

Done.

Next:
  1. In QLab, create two Video cues targeting the two _2200 / _2201 files.
  2. Create a Memo cue and set its cue NUMBER to VLOG.
  3. Create a Script cue and paste in src/qlab-content-versioning.applescript.
  4. Fire the Script cue. With dryRun true it should report 2 cues that
     would be retargeted to the _2205 / _2206 files, plus 1 warning for
     fileofvideo_vFINAL.png.
EOF
